package connect

// ResultOf computes the winner of a game of Hex / Polygon.
//
// The board is a parallelogram of hexagonal fields, given as a set of rows.
// Player "X" connects the left edge to the right edge, and player "O" connects
// the top edge to the bottom edge. The first player to form such a connection
// wins; if neither has, the result is the empty string.
func ResultOf(lines []string) (string, error) {
	board := make([][]byte, len(lines))
	for i, line := range lines {
		board[i] = []byte(line)
	}

	if winner, ok := findWinner(board, 'X'); ok {
		return string(winner), nil
	}
	if winner, ok := findWinner(board, 'O'); ok {
		return string(winner), nil
	}
	return "", nil
}

// findWinner reports whether the given player has connected their two assigned
// edges using a breadth-first search over their stones.
func findWinner(board [][]byte, player byte) (byte, bool) {
	rows := len(board)
	if rows == 0 {
		return player, false
	}
	cols := len(board[0])
	if cols == 0 {
		return player, false
	}

	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}

	queue := [][2]int{}

	// Seed the search from the player's starting edge.
	if player == 'X' {
		// X starts from the left edge (column 0).
		for r := 0; r < rows; r++ {
			if board[r][0] == player {
				queue = append(queue, [2]int{r, 0})
				visited[r][0] = true
			}
		}
	} else {
		// O starts from the top edge (row 0).
		for c := 0; c < cols; c++ {
			if board[0][c] == player {
				queue = append(queue, [2]int{0, c})
				visited[0][c] = true
			}
		}
	}

	// The six neighbours of a cell in the hexagonal grid. Because each row is
	// shifted one cell to the right, the "up" neighbours sit at columns c and
	// c+1 while the "down" neighbours sit at columns c-1 and c.
	neighbors := [][2]int{
		{0, -1}, {0, 1}, // west, east
		{-1, 0}, {-1, 1}, // north-west, north-east
		{1, -1}, {1, 0}, // south-west, south-east
	}

	for len(queue) > 0 {
		r, c := queue[0]
		queue = queue[1:]

		// A stone on the opposite edge completes the connection. This is
		// checked on dequeue so that a 1x1 board (where the start and end
		// edges coincide) is handled correctly.
		if (player == 'X' && c == cols-1) || (player == 'O' && r == rows-1) {
			return player, true
		}

		for _, d := range neighbors {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
				continue
			}
			if visited[nr][nc] || board[nr][nc] != player {
				continue
			}
			visited[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}

	return player, false
}

